+	    hf->can_id & cpu_to_le32(CAN_ERR_LOSTARB | CAN_ERR_PROT | CAN_ERR_TRX | CAN_ERR_ACK))
 		return true;
 
 	return false;
@@ -1182,7 +1183,7 @@ static int gs_can_open(struct net_device *netdev)
