>   	for (i = 0; i < count; ++i)
>   		writeb(buf[i], conf->base);
>   
> +	if (conf->rdwr_b)
> +		gpiod_set_value(conf->rdwr_b, GPIOD_OUT_LOW);
> +
> +	if (conf->csi_b)
> +		gpiod_set_value(conf->csi_b, GPIOD_OUT_LOW);
> +
>   	return 0;
>   }
