+
+		sensorhub->overflow_a.offset += (missed_overflows * (1ULL << 32));
+		sensorhub->overflow_b.offset += (missed_overflows * (1ULL << 32));
+
 		return cros_ec_sensorhub_ring_fifo_enable(sensorhub, true);
+	}
+
 	return 0;
